import { useEffect, useState } from "react";
import axios from "axios";

const MyBookings = () => {
  const [bookings, setBookings] = useState([]);
  const [units, setUnits] = useState([]);

  const [filterStatus, setFilterStatus] = useState("all");
  const [sortBy, setSortBy] = useState("date");

  const [selectedBooking, setSelectedBooking] = useState(null);
  const [showPayModal, setShowPayModal] = useState(false);
  const [showUpdateModal, setShowUpdateModal] = useState(false);

  const [paymentForm, setPaymentForm] = useState({
    name: "",
    cardNumber: "",
    expiry: "",
    cvv: ""
  });

  const [updateForm, setUpdateForm] = useState({
    unitId: "",
    startDate: "",
    endDate: "",
    pricePerDay: 0
  });

  const userInfo = JSON.parse(localStorage.getItem("userInfo"));
  const token = userInfo?.token;

  // ✅ Load bookings
  useEffect(() => {
    const fetchBookings = async () => {
      const { data } = await axios.get(
        "http://localhost:5001/api/bookings/my",
        { headers: { Authorization: `Bearer ${token}` } }
      );
      setBookings(data);
    };

    if (token) fetchBookings();
  }, [token]);

  // ✅ Load units
  useEffect(() => {
    const fetchUnits = async () => {
      const { data } = await axios.get("http://localhost:5001/api/units");
      setUnits(data);
    };
    fetchUnits();
  }, []);

  // ✅ Calculate dynamic cost
  const calculateUpdatedCost = () => {
    if (!updateForm.startDate || !updateForm.endDate) return 0;

    const start = new Date(updateForm.startDate);
    const end = new Date(updateForm.endDate);

    start.setHours(0, 0, 0, 0);
    end.setHours(0, 0, 0, 0);

    const diff = end - start;
    const days = Math.floor(diff / (1000 * 60 * 60 * 24)) + 1;

    return days > 0 ? days * updateForm.pricePerDay : 0;
  };

  // ✅ filter + sort
  let filtered = filterStatus === "all"
    ? bookings
    : bookings.filter(b => b.status === filterStatus);

  filtered = [...filtered].sort((a, b) => {
    if (sortBy === "date") return new Date(b.createdAt) - new Date(a.createdAt);
    if (sortBy === "cost") return b.totalCost - a.totalCost;
    return 0;
  });

  return (
    <div style={{ padding: "30px" }}>
      <h2>My Bookings</h2>

      {/* controls */}
      <div style={{ marginBottom: "15px" }}>
        <label>Status: </label>
        <select onChange={(e) => setFilterStatus(e.target.value)}>
          <option value="all">All</option>
          <option value="pending">Pending</option>
          <option value="confirmed">Confirmed</option>
          <option value="cancelled">Cancelled</option>
        </select>

        <label style={{ marginLeft: "20px" }}>Sort: </label>
        <select onChange={(e) => setSortBy(e.target.value)}>
          <option value="date">Date</option>
          <option value="cost">Cost</option>
        </select>
      </div>

      <table style={table}>
        <thead>
          <tr>
            <th>Unit</th>
            <th>Start</th>
            <th>End</th>
            <th>Status</th>
            <th>Cost</th>
          </tr>
        </thead>

        <tbody>
          {filtered.map((b) => (
            <tr key={b._id}>
              <td>{b.unitId?.name}</td>
              <td>{new Date(b.startDate).toLocaleDateString()}</td>
              <td>{new Date(b.endDate).toLocaleDateString()}</td>
              <td style={statusStyle(b.status)}>{b.status}</td>

              <td>
                ${b.totalCost}

                {/* Pay */}
                {b.status === "pending" && (
                  <button
                    style={payBtnSmall}
                    onClick={() => {
                      setSelectedBooking(b);
                      setShowPayModal(true);
                    }}
                  >
                    Pay
                  </button>
                )}

                {/* Update */}
                {b.status !== "cancelled" && (
                  <button
                    style={updateBtn}
                    onClick={() => {
                      setSelectedBooking(b);
                      setUpdateForm({
                        unitId: b.unitId._id,
                        startDate: b.startDate.split("T")[0],
                        endDate: b.endDate.split("T")[0],
                        pricePerDay: b.unitId.pricePerDay
                      });
                      setShowUpdateModal(true);
                    }}
                  >
                    Update
                  </button>
                )}

                {/* Cancel */}
                {b.status !== "cancelled" && (
                  <button
                    style={cancelBtnRow}
                    onClick={async () => {
                      await axios.put(
                        `http://localhost:5001/api/bookings/cancel/${b._id}`,
                        {},
                        {
                          headers: {
                            Authorization: `Bearer ${token}`
                          }
                        }
                      );
                      window.location.reload();
                    }}
                  >
                    Cancel
                  </button>
                )}
              </td>
            </tr>
          ))}
        </tbody>
      </table>

      {/* ✅ UPDATE MODAL */}
      {showUpdateModal && selectedBooking && (
        <div style={overlay}>
          <div style={modal}>
            <h3>Update Booking</h3>

            <label>Unit</label>
            <select
              value={updateForm.unitId}
              onChange={(e) => {
                const selected = units.find(u => u._id === e.target.value);

                setUpdateForm({
                  ...updateForm,
                  unitId: e.target.value,
                  pricePerDay: selected.pricePerDay
                });
              }}
              style={input}
            >
              {units.map(u => (
                <option key={u._id} value={u._id}>
                  {u.name} (${u.pricePerDay}/day)
                </option>
              ))}
            </select>

            <label>Start Date</label>
            <input
              type="date"
              value={updateForm.startDate}
              onChange={(e) =>
                setUpdateForm({ ...updateForm, startDate: e.target.value })
              }
              style={input}
            />

            <label>End Date</label>
            <input
              type="date"
              value={updateForm.endDate}
              onChange={(e) =>
                setUpdateForm({ ...updateForm, endDate: e.target.value })
              }
              style={input}
            />

            <p><b>New Cost:</b> ${calculateUpdatedCost()}</p>

            <button
              style={primaryBtn}
              onClick={async () => {
                await axios.put(
                  `http://localhost:5001/api/bookings/update/${selectedBooking._id}`,
                  {
                    unitId: updateForm.unitId,
                    startDate: updateForm.startDate,
                    endDate: updateForm.endDate
                  },
                  {
                    headers: {
                      Authorization: `Bearer ${token}`
                    }
                  }
                );

                window.location.reload();
              }}
            >
              Save
            </button>

            <button style={cancelBtn} onClick={() => setShowUpdateModal(false)}>
              Close
            </button>
          </div>
        </div>
      )}
    </div>
  );
};

const table = { width: "100%" };
const input = { padding: "8px", marginTop: "8px", width: "100%" };

const overlay = {
  position: "fixed",
  top: 0,
  left: 0,
  width: "100%",
  height: "100%",
  background: "rgba(0,0,0,0.5)",
  display: "flex",
  justifyContent: "center",
  alignItems: "center"
};

const modal = {
  background: "white",
  padding: "20px",
  borderRadius: "10px",
  width: "320px"
};

const payBtnSmall = { marginLeft: 8, background: "green", color: "white" };
const updateBtn = { marginLeft: 8, background: "orange", color: "white" };
const cancelBtnRow = { marginLeft: 8, background: "red", color: "white" };

const primaryBtn = { marginTop: 10, background: "blue", color: "white" };
const cancelBtn = { marginTop: 5 };

const statusStyle = (status) => ({
  color: status === "confirmed" ? "green" :
         status === "pending" ? "orange" : "red"
});

export default MyBookings;
